insert into public.weeks (number, title, description, published) values (1, 'Session 01 — Foundations', 'One question runs through this session: what could derail you on the way to becoming a successful coach? We name it now, while it costs nothing.', true) on conflict (number) do update set title = excluded.title, description = excluded.description, published = excluded.published;
insert into public.weeks (number, title, description, published) values (2, 'Session 02 — Niche', 'Generate wide, narrow later, research the last three — then we pick one together on the call.', true) on conflict (number) do update set title = excluded.title, description = excluded.description, published = excluded.published;
insert into public.weeks (number, title, description, published) values (3, 'Session 03 — Message', 'Your client is the hero of this story and you are the guide. This session gives you the words — and your announcement goes out at the end of it.', false) on conflict (number) do update set title = excluded.title, description = excluded.description, published = excluded.published;
insert into public.weeks (number, title, description, published) values (4, 'Session 04 — Structure & Offer', 'The map and the number. By the end of this session you have something somebody can buy.', false) on conflict (number) do update set title = excluded.title, description = excluded.description, published = excluded.published;
insert into public.weeks (number, title, description, published) values (5, 'Session 05 — Creation', 'We build your first session together, in the hour, from a template. There is a floor you only have to clear.', false) on conflict (number) do update set title = excluded.title, description = excluded.description, published = excluded.published;
insert into public.weeks (number, title, description, published) values (6, 'Session 06 — The Conversation', 'The discovery call, step by step — a conversation you are already unusually good at, with a structure for the last ten minutes.', false) on conflict (number) do update set title = excluded.title, description = excluded.description, published = excluded.published;
insert into public.weeks (number, title, description, published) values (7, 'Session 07 — Launch', 'Volume, done properly. The whole list worked — and the number that makes a first client likely rather than lucky.', false) on conflict (number) do update set title = excluded.title, description = excluded.description, published = excluded.published;
